"""Render the backend's OpenAPI schema as the REST API reference page.

`make generate-docs-api` exports a fresh schema from the backend and runs
this; `make check-docs-api` fails when the committed page is out of date.

Usage: openapi_to_markdown.py <openapi.json> <output.md>
"""

from __future__ import annotations

import json
import sys
from pathlib import Path
from typing import Any

_METHOD_ORDER = ["get", "post", "put", "patch", "delete"]

_HEADER = """\
# REST API

<!-- Generated by `make generate-docs-api` from the backend's OpenAPI
schema. Do not edit by hand: `make check-docs-api` fails on any change. -->

The web app, the desktop app and the phone app all use this API, and you
can call it from your own scripts. Every route lives under `/api` on the
same address as the web app.

Except for `/api/health` and the sign-in routes under `/api/auth`, every
request needs an `Authorization: Bearer <token>` header. The token is either
the access token returned by `POST /api/auth/login`, or a personal API token
created in **Settings** (it starts with `cbm_pat_`). Agents usually connect
through [MCP](../agents/index.md) instead.

Schema version {version}.
"""


# One line per area of the API. Route docstrings are written for developers,
# so the page uses these and the route summaries instead.
_AREA_INTROS = {
    "Account": "The signed-in account: its password and its sign-in provider link.",
    "Accounts": "Every account on the server. Admins only.",
    "Attachments": "Images embedded in notes.",
    "Auth": "Signing in, registering with an invite, and refreshing a session.",
    "Graph": "The link graph between notes.",
    "Health": "Whether the server and its vault are up. Needs no token.",
    "Invites": "Invite tokens for new accounts. Admins only.",
    "Notes": "Read, create, update, move and delete notes, and list backlinks.",
    "Search": "Full-text search with the `#tag` syntax described in "
    "[Tags and search](../features/index.md).",
    "Tasks": "Tasks collected from every note.",
    "Tokens": "Personal API tokens for scripts and MCP clients.",
    "Vault settings": "The vault's folder conventions, link format and read-only flag.",
}
_SUMMARY_NOISE = (" Endpoint", " Route")


def _area(path: str) -> str:
    segment = path.removeprefix("/api/").split("/", 1)[0]
    return segment.replace("-", " ").capitalize() or "Root"


def _ref_name(ref: str) -> str:
    return ref.rsplit("/", 1)[-1]


def _type(schema: dict[str, Any], link: bool = False) -> str:
    if "$ref" in schema:
        name = _ref_name(schema["$ref"])
        return f"[`{name}`](#{name.lower()})" if link else f"`{name}`"
    if "anyOf" in schema:
        return " or ".join(_type(option, link) for option in schema["anyOf"])
    kind = schema.get("type")
    if kind == "array":
        return f"array of {_type(schema.get('items', {}), link)}"
    if kind == "object" and "additionalProperties" in schema:
        return f"map of {_type(schema['additionalProperties'], link)}"
    if "enum" in schema:
        return " or ".join(f"`{value}`" for value in schema["enum"])
    return str(kind) if kind else "any"


def _operation(method: str, path: str, op: dict[str, Any]) -> list[str]:
    summary = op.get("summary", "")
    for noise in _SUMMARY_NOISE:
        summary = summary.removesuffix(noise)
    lines = [f"### `{method.upper()} {path}`", "", summary.capitalize(), ""]
    parameters = op.get("parameters", [])
    if parameters:
        lines += ["| Parameter | In | Required | Type |", "|---|---|---|---|"]
        for param in parameters:
            required = "yes" if param.get("required") else "no"
            kind = _type(param.get("schema", {}))
            lines.append(f"| `{param['name']}` | {param['in']} | {required} | {kind} |")
        lines.append("")
    body = op.get("requestBody", {}).get("content", {})
    for media, content in body.items():
        kind = _type(content.get("schema", {}), True)
        lines += [f"Request body: `{media}` ({kind})", ""]
    ok = op.get("responses", {}).get("200", {}).get("content", {})
    for content in ok.values():
        lines += [f"Returns: {_type(content.get('schema', {}), True)}", ""]
    return lines


def _schema(name: str, schema: dict[str, Any]) -> list[str]:
    lines = [f"### {name}", ""]
    properties = schema.get("properties", {})
    if not properties:
        return [*lines, _type(schema), ""]
    required = set(schema.get("required", []))
    lines += ["| Field | Type | Required |", "|---|---|---|"]
    for field, spec in properties.items():
        flag = "yes" if field in required else "no"
        lines.append(f"| `{field}` | {_type(spec, True)} | {flag} |")
    return [*lines, ""]


def render(schema: dict[str, Any]) -> str:
    areas: dict[str, list[tuple[int, str, str, dict[str, Any]]]] = {}
    for path, operations in schema["paths"].items():
        for method, op in operations.items():
            order = _METHOD_ORDER.index(method) if method in _METHOD_ORDER else 99
            areas.setdefault(_area(path), []).append((order, path, method, op))

    lines = [_HEADER.format(version=schema["info"]["version"])]
    for area in sorted(areas):
        lines += [f"## {area}", ""]
        if area in _AREA_INTROS:
            lines += [_AREA_INTROS[area], ""]
        for _, path, method, op in sorted(areas[area], key=lambda e: (e[1], e[0])):
            lines += _operation(method, path, op)
    schemas = schema.get("components", {}).get("schemas", {})
    if schemas:
        lines += ["## Schemas", ""]
        for name in sorted(schemas):
            lines += _schema(name, schemas[name])
    return "\n".join(lines).rstrip() + "\n"


def main(argv: list[str]) -> int:
    if len(argv) != 3:
        print(__doc__, file=sys.stderr)
        return 2
    schema = json.loads(Path(argv[1]).read_text(encoding="utf-8"))
    Path(argv[2]).write_text(render(schema), encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
